1	/**
2	 * track.ts — the SINGLE analytics choke point (spec §7.1).
3	 *
4	 * Game code never touches gtag/fbq directly; it calls the typed `track()`
5	 * overloads, which fan out to GA4 (gtag) and Meta Pixel (fbq). Everything here
6	 * is safe when the pixels are absent/blocked (optional chaining) and gated on a
7	 * consent hook. Real GA4/Pixel loading is finished in Phase 5 — `initAnalytics`
8	 * already env-gates the loader so no live IDs are hardcoded.
9	 */
10	
11	import { ENV } from '../config/env';
12	
13	declare global {
14	  interface Window {
15	    gtag?: (...args: unknown[]) => void;
16	    fbq?: ((...args: unknown[]) => void) & { callMethod?: (...args: unknown[]) => void };
17	    dataLayer?: unknown[];
18	    _fbq?: unknown;
19	  }
20	}
21	
22	/** The three funnel events — names are FIXED by the brief (§3B); do not rename. */
23	export type AnalyticsEvent = 'start_game' | 'finish_game' | 'click_buy';
24	
25	/** `start_game` — a round begins. No params required (spec §7.2). */
26	export type StartGameParams = Record<string, never>;
27	
28	/** `finish_game` — a round ends (win OR lose) (spec §7.2). */
29	export interface FinishGameParams {
30	  result: 'win' | 'lose';
31	  score: number;
32	  /** Active play time in seconds, EXCLUDING paused time. */
33	  duration_s: number;
34	}
35	
36	/** `click_buy` — the results-screen CTA was tapped (spec §7.2). */
37	export interface ClickBuyParams {
38	  destination: string;
39	  promo_code: string;
40	}
41	
42	// ── Consent gate (spec §7.4) ───────────────────────────────────────────────
43	// The adapter ships "consent-ready": a single flag every event passes through.
44	// A future CMP flips it via setAnalyticsConsent(); until then it defaults to
45	// granted so the funnel is observable in dev/QA.
46	let consentGranted = true;
47	
48	export function setAnalyticsConsent(granted: boolean): void {
49	  consentGranted = granted;
50	}
51	
52	function hasConsent(): boolean {
53	  return consentGranted;
54	}
55	
56	// ── track() — typed overloads so call sites get the right param shape ──────
57	export function track(event: 'start_game', params?: StartGameParams): void;
58	export function track(event: 'finish_game', params: FinishGameParams): void;
59	export function track(event: 'click_buy', params: ClickBuyParams): void;
60	// Implementation signature: `object` is the loosest supertype of every event's
61	// param shape (interfaces aren't assignable to Record<string, unknown> in TS).
62	export function track(event: AnalyticsEvent, params: object = {}): void {
63	  if (!hasConsent()) return;
64	
65	  // GA4
66	  window.gtag?.('event', event, params);
67	  // Meta Pixel — custom events via trackCustom
68	  window.fbq?.('trackCustom', event, params);
69	
70	  if (ENV.debugAnalytics) {
71	    // Intentional QA mirror, gated behind VITE_DEBUG_ANALYTICS.
72	    console.debug('[track]', event, params);
73	  }
74	}
75	
76	// ── initAnalytics() — env-gated loader (called once from main.ts) ──────────
77	// Injects the GA4 / Pixel bootstraps ONLY when their IDs are present and consent
78	// is granted. With no IDs (dev/preview) this is a no-op and track() stays safe.
79	let initialized = false;
80	
81	export function initAnalytics(): void {
82	  if (initialized || !hasConsent()) return;
83	  initialized = true;
84	
85	  if (ENV.ga4Id) loadGa4(ENV.ga4Id);
86	  if (ENV.fbPixelId) loadPixel(ENV.fbPixelId);
87	}
88	
89	function loadGa4(measurementId: string): void {
90	  const s = document.createElement('script');
91	  s.async = true;
92	  s.src = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(measurementId)}`;
93	  document.head.appendChild(s);
94	
95	  window.dataLayer = window.dataLayer ?? [];
96	  const gtag: (...args: unknown[]) => void = (...args) => {
97	    window.dataLayer?.push(args);
98	  };
99	  window.gtag = gtag;
100	  gtag('js', new Date());
101	  gtag('config', measurementId);
102	}
103	
104	function loadPixel(pixelId: string): void {
105	  if (!window.fbq) {
106	    const fbq = ((...args: unknown[]) => {
107	      fbq.callMethod ? fbq.callMethod(...args) : fbq.queue.push(args);
108	    }) as ((...args: unknown[]) => void) & {
