9	 */
10	
11	function readStoredMute(): boolean {
12	  try {
13	    return localStorage.getItem(MUTE_STORAGE_KEY) === '1';
14	  } catch {
15	    return false; // private mode / storage disabled
16	  }
17	}
18	
19	function persistMute(value: boolean): void {
20	  try {
21	    localStorage.setItem(MUTE_STORAGE_KEY, value ? '1' : '0');
22	  } catch {
23	    /* ignore — non-persistent session is acceptable */
24	  }
25	}
26	
27	let muted = readStoredMute();
28	let unlockInstalled = false;
29	
30	export const AudioManager = {
31	  isMuted(): boolean {
32	    return muted;
33	  },
34	
35	  /** Push the persisted mute state onto a game's sound manager. */
36	  apply(sound: Phaser.Sound.BaseSoundManager): void {
37	    sound.mute = muted;
38	  },
39	
40	  /** Toggle mute, persist, and apply. Returns the new muted state. */
41	  toggle(sound: Phaser.Sound.BaseSoundManager): boolean {
42	    muted = !muted;
43	    sound.mute = muted;
44	    persistMute(muted);
45	    return muted;
46	  },
47	
48	  /**
49	   * iOS Safari / autoplay audio-unlock. WebAudio is suspended until a real user
50	   * gesture, so resume the context on the first one.
51	   *
52	   * This MUST NOT bind to a scene's InputPlugin: PreloadScene's input shuts down
53	   * the instant it hands off to Menu (InputPlugin.shutdown removes the listener),
54	   * so the gesture would never be seen. Instead attach a single LONG-LIVED
55	   * window listener (survives every scene transition) that resumes once, then
56	   * removes itself. Idempotent — safe to call before any audio assets exist.
57	   * TODO(phase-5): verify on real iOS Safari, and confirm a muted player who
58	   * taps Play stays muted through the unlock.
59	   */
60	  installAudioUnlock(sound: Phaser.Sound.BaseSoundManager): void {
61	    if (unlockInstalled) return;
62	    unlockInstalled = true;
63	
64	    const resume = (): void => {
65	      if (
66	        sound instanceof Phaser.Sound.WebAudioSoundManager &&
67	        sound.context.state === 'suspended'
68	      ) {
69	        void sound.context.resume();
70	      }
71	      window.removeEventListener('pointerdown', resume);
72	      window.removeEventListener('touchend', resume);
73	    };
74	
75	    // Either gesture unlocks; whichever fires first tears both down.
76	    window.addEventListener('pointerdown', resume);
77	    window.addEventListener('touchend', resume);
78	  },
79	};
